#!/usr/bin/env python3
"""Final verification pass."""
import json
import sys
from concurrent.futures import ThreadPoolExecutor, as_completed
from netmiko import ConnectHandler

def run_cmd(host, dtype, user, pwd, cmds):
    results = {}
    try:
        conn = ConnectHandler(host=host, device_type=dtype, username=user, password=pwd)
        for cmd in cmds:
            try:
                results[cmd] = conn.send_command(cmd, read_timeout=30)
            except Exception as e:
                results[cmd] = f"ERROR: {e}"
        conn.disconnect()
    except Exception as e:
        results["connection"] = f"ERROR: {e}"
    return results

def verify_routers():
    tasks = {}

    # HQ-Edge
    tasks["HQ-Edge"] = ("192.168.122.11", "vyos", "vyos", "test", [
        "show ip ospf neighbor",
        "show ip bgp summary",
        "show ip bgp",
        "show ip route",
        "show nat source rules",
        "show ip bgp neighbors 203.0.113.1 advertised-routes",
        "show ip bgp neighbors 203.0.113.5 advertised-routes",
    ])

    # Hub-A
    tasks["Hub-A"] = ("192.168.122.12", "vyos", "vyos", "test", [
        "show ip ospf neighbor",
        "show ip route",
        "show ip ospf interface",
    ])

    # Hub-B
    tasks["Hub-B"] = ("192.168.122.13", "vyos", "vyos", "test", [
        "show ip ospf neighbor",
        "show ip route",
        "show ip ospf interface",
    ])

    # Branches
    for i, (name, host) in enumerate([
        ("Branch-1", "192.168.122.21"),
        ("Branch-2", "192.168.122.22"),
        ("Branch-3", "192.168.122.23"),
        ("Branch-4", "192.168.122.24"),
    ]):
        tasks[name] = (host, "mikrotik_routeros", "admin", "test", [
            "/ip route print terse",
            "/routing ospf neighbor print detail",
        ])

    results = {}
    with ThreadPoolExecutor(max_workers=7) as pool:
        futures = {}
        for name, (host, dtype, user, pwd, cmds) in tasks.items():
            futures[pool.submit(run_cmd, host, dtype, user, pwd, cmds)] = name
        for f in as_completed(futures):
            name = futures[f]
            results[name] = f.result()
            print(f"[OK] {name}", file=sys.stderr)

    return results

def verify_pings():
    """Test host reachability."""
    non_guest = {
        "B1-PC1": ("192.168.122.31", "10.1.1.10"),
        "B1-PC2": ("192.168.122.32", "10.1.1.11"),
        "B2-PC1": ("192.168.122.33", "10.1.2.10"),
        "B2-PC2": ("192.168.122.34", "10.1.2.11"),
        "B3-PC1": ("192.168.122.35", "10.1.3.10"),
        "B3-PC2": ("192.168.122.36", "10.1.3.11"),
        "B4-PC1": ("192.168.122.37", "10.2.1.10"),
        "B4-PC2": ("192.168.122.38", "10.2.1.11"),
    }
    guest = {
        "B4-PC3": ("192.168.122.39", "10.2.2.10"),
        "B4-PC4": ("192.168.122.40", "10.2.2.11"),
    }

    all_hosts = {**non_guest, **guest}
    internet_targets = ["8.8.8.8", "1.1.1.1"]

    # Build ping commands per host
    ping_tasks = {}
    for name, (mgmt, lab_ip) in all_hosts.items():
        targets = []
        # Ping all other hosts
        for other_name, (_, other_lab) in all_hosts.items():
            if other_name != name:
                targets.append((other_name, other_lab))
        # Ping internet
        for t in internet_targets:
            targets.append((t, t))

        cmds = []
        for tname, tip in targets:
            cmds.append(f"ping -c 2 -W 3 {tip}")

        ping_tasks[name] = (mgmt, targets, cmds)

    results = {}

    def do_pings(name, mgmt, targets, cmds):
        res = {}
        try:
            conn = ConnectHandler(host=mgmt, device_type="linux", username="root", password="alpine")
            for (tname, tip), cmd in zip(targets, cmds):
                try:
                    out = conn.send_command(cmd, read_timeout=15)
                    success = "0% packet loss" in out or "0 received" not in out
                    # More precise check
                    if "0 packets received" in out or "100% packet loss" in out:
                        success = False
                    elif "bytes from" in out:
                        success = True
                    else:
                        success = False
                    res[f"{name}->{tname}({tip})"] = "PASS" if success else "FAIL"
                except Exception as e:
                    res[f"{name}->{tname}({tip})"] = f"ERROR: {e}"
            conn.disconnect()
        except Exception as e:
            res[f"{name}->connection"] = f"ERROR: {e}"
        return name, res

    with ThreadPoolExecutor(max_workers=10) as pool:
        futures = []
        for name, (mgmt, targets, cmds) in ping_tasks.items():
            futures.append(pool.submit(do_pings, name, mgmt, targets, cmds))
        for f in as_completed(futures):
            name, res = f.result()
            results.update(res)
            print(f"[PING OK] {name}", file=sys.stderr)

    return results, non_guest, guest

def main():
    print("=== ROUTER VERIFICATION ===")
    router_results = verify_routers()
    for name in ["HQ-Edge", "Hub-A", "Hub-B", "Branch-1", "Branch-2", "Branch-3", "Branch-4"]:
        print(f"\n--- {name} ---")
        for cmd, out in router_results.get(name, {}).items():
            print(f"  [{cmd}]")
            print(f"  {out[:2000]}")

    print("\n\n=== PING VERIFICATION ===")
    ping_results, non_guest, guest = verify_pings()

    non_guest_names = set(non_guest.keys())
    guest_names = set(guest.keys())

    # Categorize results
    ng_to_ng_pass = 0
    ng_to_ng_fail = 0
    ng_to_ng_fails = []
    guest_to_guest_pass = 0
    guest_to_guest_fail = 0
    guest_cross_pass = 0  # should be 0
    guest_cross_fail = 0  # should be 32
    guest_cross_passes = []
    internet_pass = 0
    internet_fail = 0
    internet_fails = []

    for key, result in sorted(ping_results.items()):
        src = key.split("->")[0]
        dst_part = key.split("->")[1]
        dst_name = dst_part.split("(")[0]

        is_src_guest = src in guest_names
        is_dst_guest = dst_name in guest_names
        is_internet = dst_name in ["8.8.8.8", "1.1.1.1"]

        if is_internet:
            if result == "PASS":
                internet_pass += 1
